import { MenuHeader } from '@kerfjs/ui/menu-header';
import { MenuItem } from '@kerfjs/ui/menu-item';
import '@kerfjs/ui/layout.css';
import './navigation.css';

type Route = 'overview' | 'projects' | 'activity' | 'people';
export function Navigation({ current, navigate, onSettings, onHelp }: {
 current: Route; navigate: (route: Route) => void; onSettings: () => void; onHelp: () => void;
}) {
 return <nav className="kui-layout kui-sidebar navigation" aria-label="Main navigation">
   <section className="kui-sidebar-section" aria-label="Workspace">
     <MenuHeader>Workspace</MenuHeader>
     <MenuItem aria-current={current === 'overview' ? 'page' : undefined} onClick={() => navigate('overview')} icon={<span aria-hidden="true">⌂</span>}>Overview</MenuItem>
     <MenuItem aria-current={current === 'projects' ? 'page' : undefined} onClick={() => navigate('projects')}>Projects</MenuItem>
     <MenuItem aria-current={current === 'activity' ? 'page' : undefined} onClick={() => navigate('activity')}>Activity</MenuItem>
   </section>
   <section className="kui-sidebar-section" aria-label="Organization">
     <MenuHeader>Organization</MenuHeader>
     <MenuItem aria-current={current === 'people' ? 'page' : undefined} onClick={() => navigate('people')} icon={<span aria-hidden="true">♙</span>}>People</MenuItem>
     <MenuItem disabled aria-disabled="true">Billing — unavailable</MenuItem>
   </section>
   <section className="kui-sidebar-surface" aria-label="Workspace summary"><strong>Design studio</strong><p>12 projects · 8 members</p></section>
   <footer className="navigation-footer"><button type="button" onClick={onSettings}>Settings</button><button type="button" onClick={onHelp}>Help</button></footer>
 </nav>;
}

